mapper.select:
SELECT l.id, l.warehouse_id, w.name AS warehouse_name, l.code, l.name, l.zone, l.loc_type, l.sort, l.status, l.remark, l.create_time, l.update_time FROM wms_location l JOIN wms_warehouse w ON w.id = l.warehouse_id
l.warehouse_id = #{warehouseId}
AND (l.code LIKE CONCAT('%', #{keyword}, '%') OR l.name LIKE CONCAT('%', #{keyword}, '%'))
AND l.status = #{status}
ORDER BY w.sort, w.id, l.zone, l.sort, l.code
